import { voxClient } from './client'

export type RelatedEntity = {
  id: string
  type: string
  title: string
  relevanceScore: number
}

export const voxRelated = {
  async getRelated(entityId: string, entityType: string): Promise<RelatedEntity[]> {
    return voxClient.fetch<RelatedEntity[]>('/related', {
      method: 'POST',
      body: JSON.stringify({ entityId, entityType }),
    })
  },
}
